from pathlib import Path
import json
import html

root = Path(__file__).resolve().parents[1]
colors = {'orange':'#FF7900','navy':'#062536','white':'#FFFFFF','cloud':'#F4F6F7','slate':'#526570'}
(root/'specifications/colors.json').write_text(json.dumps(colors,indent=2)+'\n')
(root/'specifications/tokens.css').write_text(':root {\n'+''.join(f'  --pich-{k}: {v};\n' for k,v in colors.items())+'  --pich-body: Inter, Arial, sans-serif;\n  --pich-display: Oxanium, Arial, sans-serif;\n}\n')
swatches=[]
for key,value in colors.items():
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300" viewBox="0 0 400 300"><rect width="400" height="300" fill="{value}"/></svg>'
    (root/f'specifications/swatch-{key}.svg').write_text(svg)
    swatches.append(f'<div class="swatch"><div style="background:{value}"></div><strong>{key.title()}</strong><code>{value}</code></div>')

names=[('mark-color','Standalone P · color'),('mark-navy','Standalone P · navy'),('mark-white','Standalone P · white'),('circle-orange-white','Preferred circle · white on orange'),('circle-navy-white','One-ink circle · navy / knockout'),('circle-navy-orange','Alternate circle · orange on navy'),('wordmark-color','Wordmark · color'),('wordmark-navy','Wordmark · navy'),('wordmark-white','Wordmark · white'),('lockup-color','Primary F lockup'),('lockup-navy','F lockup · navy'),('lockup-white','F lockup · white')]
cards=''.join(f'<figure><a href="logos/{n}.png"><img src="logos/{n}.png" alt="{label}" loading="lazy"></a><figcaption>{label}<a href="logos/{n}.png" download>PNG ↓</a></figcaption></figure>' for n,label in names)
style='''*{box-sizing:border-box}body{margin:0;background:#F4F6F7;color:#062536;font-family:Inter,Arial,sans-serif;line-height:1.55}main{max-width:1180px;margin:auto;padding:60px 40px}h1{font-size:56px;letter-spacing:-2px;line-height:1.1;margin:16px 0}h2{font-size:30px;margin-top:55px}h3{margin-bottom:8px}a{color:inherit;text-decoration-thickness:1px;text-underline-offset:4px}p{max-width:850px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#526570}.intro{font-size:20px}.hero{background:white;padding:35px;border-radius:12px;margin-top:30px}.hero img{width:100%;max-height:430px;object-fit:contain}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}figure{margin:0;background:white;border:1px solid #dce3e6;border-radius:8px;overflow:hidden}figure img{width:100%;height:220px;object-fit:contain;display:block}figcaption{font-size:12px;padding:14px;border-top:1px solid #eef1f2}figcaption a{float:right}.swatches{display:grid;grid-template-columns:repeat(5,1fr);gap:15px}.swatch{background:white;border:1px solid #dce3e6;padding-bottom:18px}.swatch>div{height:125px;margin-bottom:15px;border-bottom:1px solid #eef1f2}.swatch strong,.swatch code{display:block;margin:0 16px}.swatch code{color:#526570}.panel{background:white;padding:28px;border-left:3px solid #FF7900;margin:20px 0}.specimen{font-family:Oxanium,Arial,sans-serif;font-weight:500;font-size:26px;letter-spacing:.08em}.wide{width:100%;height:auto;border-radius:8px}table{border-collapse:collapse;width:100%;background:white;font-size:14px}td,th{text-align:left;vertical-align:top;padding:16px;border-bottom:1px solid #e2e8eb}th{background:#062536;color:white}.note{font-size:13px;color:#526570}.links{display:flex;gap:20px;flex-wrap:wrap}.button{background:#062536;color:white;padding:11px 18px;border-radius:5px;text-decoration:none;display:inline-block}.rule{height:4px;width:65px;background:#FF7900;margin-top:30px}@media(max-width:760px){main{padding:30px 18px}h1{font-size:38px}.grid{grid-template-columns:1fr}.swatches{grid-template-columns:repeat(2,1fr)}}@media print{body{background:white}main{padding:0}figure{break-inside:avoid}h2{break-after:avoid}.button{display:none}}'''
content=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pich · Brand identity draft 1</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Oxanium:wght@500&display=swap" rel="stylesheet"><style>{style}</style><main>
<div class="eyebrow">Pich / Brand identity / Draft 01 / November 2026</div><h1>Built around a distinctive P.</h1><p class="intro">A compact mark, a confident wordmark, and a quieter descriptor. Direction F pairs the name with an orange leading rule and right-aligned <strong>Roofing Software</strong>.</p><div class="links"><a class="button" href="BRAND-GUIDE.md">Written specifications</a><a class="button" href="applications.html">Editable stationery drafts</a><a href="specifications/colors.json">Color tokens</a></div>
<div class="hero"><img src="logos/lockup-color.png" alt="Pich primary F lockup"></div>
<p class="note">Draft raster assets on solid backgrounds. These are review files, not transparent vector production masters. Separate generations can differ slightly in shape. Exact production colors are specified below.</p>
<h2>01 / Logo family</h2><p>Use the descriptor for introductions and sales materials. Use the plain wordmark when context is established, and the P badge for compact placements. White-on-orange is the preferred circle treatment.</p><div class="grid">{cards}</div>
<h2>02 / Plain color swatches</h2><div class="swatches">{''.join(swatches)}</div><p>Orange and Navy form the identity. White supplies breathing room; Cloud and Slate support documents and product layouts. The SVG swatches and JSON/CSS tokens contain exact values, unlike color approximations in generated artwork.</p>
<h2>03 / Typography</h2><div class="panel"><h3>Pich custom wordmark</h3><p>Generated custom lettering, not an identified retail font. Retain it as artwork and create a single outlined master before final production.</p></div><div class="panel"><h3>Oxanium Medium · proposed descriptor font</h3><div class="specimen">ROOFING SOFTWARE</div><p>Squared geometry, medium weight, modest tracking. Keep the descriptor around 75% of the wordmark width and right aligned; place the orange leading rule in the remaining space.</p><a href="https://github.com/sevmeyer/oxanium">Official source and SIL Open Font License</a></div><div class="panel"><h3>Inter · supporting type family</h3><p class="intro">Clear communication, from the office to the field.</p><p>Regular 400 for body copy; Medium 500 for labels; SemiBold 600 for headings. Use for contact details, correspondence, presentations, and product UI.</p><a href="https://rsms.me/inter/">Official source and SIL Open Font License</a></div><p class="note">The two font families are proposed production choices, not identifications of generated raster lettering. Live specimens request Google Fonts when online; Arial is the fallback. Fonts are not bundled.</p>
<h2>04 / Draft applications</h2><img class="wide" src="previews/applications.png" alt="Draft Pich applications on cards, letterhead, envelope, apparel and a phone"><p class="note">Concept mockups, not print-ready files. Contact details are placeholders. Editable card and letterhead layouts are available in <a href="applications.html">the stationery draft</a>.</p>
<table><tr><th>Placement</th><th>Recommended treatment</th></tr><tr><td>Business cards</td><td>F lockup on white front; preferred orange badge on navy back. Name and contact details in Inter.</td></tr><tr><td>Letterhead and proposals</td><td>Small F lockup at upper left, ample white space, a restrained orange rule in the contact footer.</td></tr><tr><td>Hats and polos</td><td>Standalone P or orange circle patch. Omit the descriptor and proof embroidery at actual size.</td></tr><tr><td>App and social</td><td>White P on orange. Adapt the outside container to the platform's required mask without distorting the P.</td></tr><tr><td>Email signatures</td><td>Compact wordmark plus live name, role, and contact text; avoid rendering the entire signature as an image.</td></tr></table>
<h2>05 / Use and handoff</h2><p>Allow approximately one quarter of the P's height as clear space. Keep the diagonal channel open. Do not stretch the logo, add effects, or retype the wordmark. Drop the descriptor at small sizes.</p><p>Before production: approve one vector master, derive all variants from it, replace sample contact information, and proof print colors and embroidery. The generated transparent attempts had halos and are excluded from this package; the final review PNGs use clean solid backgrounds.</p><div class="rule"></div><p class="note">Created with built-in ImageGen for logo previews and mockups, plus deterministic HTML/CSS and SVG swatches. Prompts and asset checks are included in specifications/.</p></main></html>'''
(root/'brand-book.html').write_text(content,encoding='utf-8')

applications='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pich · Stationery drafts</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap" rel="stylesheet"><style>
*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#e8edef;color:#062536;margin:0;padding:40px}header{max-width:900px;margin:auto}h1{margin:0}a{color:inherit}.cards{display:flex;gap:25px;flex-wrap:wrap;margin:30px auto;max-width:900px}.card{width:3.5in;height:2in;background:white;padding:.18in;position:relative;box-shadow:0 8px 24px #06253618}.card .logo{width:1.7in;height:.65in;object-fit:contain;object-position:left center}.details{font-size:8pt;line-height:1.45;margin-top:8px}.details b{font-size:11pt}.back{background:#062536;display:flex;align-items:center;justify-content:center}.back img{width:1.1in;height:1.1in;object-fit:cover;clip-path:circle(43% at 50% 50%)}.letter{width:8.5in;min-height:11in;padding:.65in .75in;margin:40px auto;background:white;box-shadow:0 8px 24px #06253618;position:relative}.letter img{width:2.3in;height:1.05in;object-fit:contain;object-position:left center}.letter article{margin-top:.6in;font-size:11pt;line-height:1.55}.letter h2{font-size:19pt}.letter footer{position:absolute;bottom:.55in;left:.75in;right:.75in;border-top:2px solid #FF7900;padding-top:12px;font-size:8pt;display:flex;justify-content:space-between}.note{font-size:13px;color:#526570}.signature{background:white;padding:24px;max-width:600px;margin:30px auto;font-size:14px;border-left:3px solid #FF7900}.signature img{width:140px;display:block;margin-bottom:12px}.signature p{margin:4px 0}@media print{@page{size:letter;margin:0}body{padding:0;background:white}header,.cards,.signature{display:none}.letter{margin:0;box-shadow:none;break-after:page}}@media(max-width:850px){body{padding:20px}.letter{width:100%;min-height:900px;padding:35px}.letter footer{left:35px;right:35px}}
</style><header><a href="brand-book.html">← Brand book</a><h1>Stationery drafts</h1><p>Editable layout concepts using the review artwork. Contact details below are placeholders.</p><p class="note">Cards: 3.5 × 2in trim. Letterhead: US Letter. Print view shows only letterhead. These layouts have not been prepared as press-ready files; add printer-requested bleed and final vector logos before ordering.</p></header>
<section class="cards"><div class="card"><img class="logo" src="logos/lockup-color.png" alt="Pich"><div class="details"><b>Adam Johnson</b><br>Role / Title<br>hello@pich.example · +1 312 555 0100<br>pich.example</div></div><div class="card back"><img src="logos/circle-orange-white.png" alt="Pich badge"></div></section>
<section class="letter"><img src="logos/lockup-color.png" alt="Pich Roofing Software"><article><p>November 19, 2026</p><p>Recipient Name<br>Company Name<br>Street Address<br>City, State ZIP</p><h2>A clearer view of every job.</h2><p>Dear Recipient,</p><p>This sample letter demonstrates Pich's correspondence layout. Keep the logo compact, use navy for readable body text, and let generous white space carry the page.</p><p>Replace this copy with your message. The supporting type should remain simple and useful, leaving the custom wordmark and its orange accent to establish the identity.</p><p>Sincerely,</p><p><strong>Adam Johnson</strong><br>Role / Title</p></article><footer><span>pich.example</span><span>hello@pich.example · +1 312 555 0100</span></footer></section>
<section class="signature"><img src="logos/wordmark-color.png" alt="Pich"><p><strong>Adam Johnson</strong> · Role / Title</p><p>hello@pich.example · +1 312 555 0100</p><p>pich.example</p><p class="note">Email signature layout concept; use live contact text.</p></section></html>'''
(root/'applications.html').write_text(applications,encoding='utf-8')
print('Created brand book, stationery layouts, 5 exact SVG swatches and JSON/CSS tokens.')

